import { useCallback, useState } from "react";
import { InputText } from "@kit/index.js";
import { useDebouncedCallback, useTrack, useTranslation } from "travel-platform";
import { AutocompleteList } from "./AutocompleteList.jsx";
import { TrendingDestinations } from "./TrendingDestinations.jsx";
import styles from "./SearchBox.module.css";

export function DestinationField({ destination, trending, onChange }) {
    const t = useTranslation();
    const track = useTrack();
    const [text, setText] = useState(destination.label ?? "");
    const [query, setQuery] = useState("");
    const [open, setOpen] = useState(false);
    const [label, setLabel] = useState(destination.label);
    if (label !== destination.label) {
        setLabel(destination.label);
        setText(destination.label ?? "");
    }
    const updateQuery = useDebouncedCallback((value) => setQuery(value), 150);
    const onInput = useCallback((event) => {
        const value = event.target.value;
        setText(value);
        setOpen(true);
        updateQuery(value.trim());
    }, [updateQuery]);
    const clear = useCallback(() => {
        setText("");
        setQuery("");
        setOpen(false);
        onChange({ destId: null, destType: null, label: "" });
    }, [onChange]);
    const select = useCallback((suggestion, position) => {
        track("searchbox.autocomplete_select", { destType: suggestion.destination.destType, position, length: query.length });
        setOpen(false);
        setText(suggestion.title);
        onChange({ destId: suggestion.destination.destId, destType: suggestion.destination.destType, label: suggestion.title });
    }, [onChange, track, query]);
    return (
        <div className={styles.field}>
            <InputText
                label={t("sb.destination")}
                placeholder={t("sb.destination")}
                value={text}
                startIcon="hotel"
                onChange={onInput}
                onFocus={() => setOpen(Boolean(query))}
                onClear={clear}
                clearLabel={t("sb.destination_clear")}
                testId="destination-input"
                inputProps={{ role: "combobox", "aria-expanded": open, "aria-autocomplete": "list", "aria-controls": "destination-suggestions", name: "ss" }}
            />
            {open && query ? <AutocompleteList query={query} onSelect={select} /> : null}
            <TrendingDestinations destinations={trending} visible={open && !query} />
        </div>
    );
}
