import { forwardRef, useId } from "react";
import styles from "./InputText.module.css";
import { Icon } from "./Icon.jsx";
import { IconButton } from "./Button.jsx";
import { cx } from "./util.js";

export const InputText = forwardRef(function InputText({ label, value, placeholder, startIcon, onChange, onFocus, onClear, clearLabel = "Clear field", className, inputProps, testId }, ref) {
    const id = useId();
    return (
        <div className={cx(styles.field, className)} data-testid={testId}>
            <label htmlFor={id} className={styles.label}>{label}</label>
            <div className={styles.control}>
                {startIcon ? <Icon name={startIcon} size="medium" className={styles.startIcon} /> : null}
                <input ref={ref} id={id} className={styles.input} value={value} placeholder={placeholder} onChange={onChange} onFocus={onFocus} autoComplete="off" {...inputProps} />
                {onClear && value ? <IconButton icon="close" label={clearLabel} size="small" className={styles.clear} onClick={onClear} data-testid={testId && `${testId}-clear`} /> : null}
            </div>
        </div>
    );
});
