import { useRef, useState } from "react";
import { Button, Checkbox, Divider, Icon, Popover, Stack, Stepper, Text } from "@kit/index.js";
import { Translate, useTranslation } from "travel-platform";
import styles from "./SearchBox.module.css";

function OccupancyPanel({ adults, children, rooms, onChange, onDone }) {
    const t = useTranslation();
    const [pets, setPets] = useState(false);
    return (
        <Stack gap={2} className={styles.occupancy} style={{ width: 320 }}>
            <Stepper label={t("sb.adults_label")} a11yLabel={t("sb.adults_label")} value={adults} min={1} max={30} onChange={(value) => onChange({ adults: value })} />
            <Stepper label={t("sb.children_label")} a11yLabel={t("sb.children_label")} value={children} min={0} max={10} onChange={(value) => onChange({ children: value })} />
            <Text variant="small_1" color="alt"><Translate id="sb.children_hint" /></Text>
            <Stepper label={t("sb.rooms_label")} a11yLabel={t("sb.rooms_label")} value={rooms} min={1} max={30} onChange={(value) => onChange({ rooms: value })} />
            <Divider />
            <Checkbox label={t("sb.pets")} sublabel={t("sb.pets_hint")} checked={pets} onChange={(e) => setPets(e.target.checked)} />
            <Button variant="secondary" wide onClick={onDone}><Translate id="sb.done" /></Button>
        </Stack>
    );
}

export function OccupancyField({ adults, children, rooms, open, onOpen, onClose, onChange }) {
    const t = useTranslation();
    const anchorRef = useRef(null);
    const summary = [t("sb.adults", { count: adults }), t("sb.children", { count: children }), t("sb.rooms", { count: rooms })].join(" · ");
    return (
        <div className={styles.field}>
            <button ref={anchorRef} type="button" className={styles.trigger} aria-label={t("sb.occupancy")} aria-expanded={open} onClick={onOpen} data-testid="occupancy-config">
                <Icon name="person" size="medium" />
                <span className={styles.triggerText}>{summary}</span>
                <Icon name="chevron-down" size="small" />
            </button>
            <Popover open={open} anchorRef={anchorRef} onClose={onClose} position="start" closeLabel={t("sb.close")}>
                <OccupancyPanel adults={adults} children={children} rooms={rooms} onChange={onChange} onDone={onClose} />
            </Popover>
        </div>
    );
}
