import { createContext, forwardRef, useCallback, useContext, useId, useMemo, useState } from "react";
import styles from "./Checkbox.module.css";
import { cx } from "./util.js";

// A form field's ids and state, for the parts of the field.
const FieldContext = createContext(null);

export function useField() {
    return useContext(FieldContext);
}

function FieldCount({ children }) {
    const field = useField();
    const id = useMemo(() => `${field.id}-count`, [field.id]);
    return <span id={id} className={styles.count}>{children}</span>;
}

function CheckboxMark() {
    const field = useField();
    const className = useMemo(() => cx(styles.box, field.checked && styles.boxChecked), [field.checked]);
    return <span className={className} aria-hidden="true" />;
}

function CheckboxLabelText({ label, sublabel }) {
    const field = useField();
    const className = useMemo(() => cx(styles.content, field.disabled && styles.contentDisabled), [field.disabled]);
    return (
        <span className={className}>
            <span className={styles.text}>{label}</span>
            {sublabel ? <span className={styles.sublabel}>{sublabel}</span> : null}
        </span>
    );
}

const CheckboxControl = forwardRef(function CheckboxControl(props, ref) {
    const field = useField();
    return (
        <span className={styles.control}>
            <input ref={ref} id={field.id} type="checkbox" className={styles.input} {...props} />
        </span>
    );
});

function useFocusVisible() {
    const [focused, setFocused] = useState(false);
    const onFocus = useCallback(() => setFocused(true), []);
    const onBlur = useCallback(() => setFocused(false), []);
    return { focused, onFocus, onBlur };
}

export const Checkbox = forwardRef(function Checkbox({ name, value, checked, disabled, label, sublabel, count, onChange, className, testId, ...rest }, ref) {
    const id = useId();
    const { focused, onFocus, onBlur } = useFocusVisible();
    const field = useMemo(() => ({ id, checked, disabled, focused }), [id, checked, disabled, focused]);
    return (
        <FieldContext.Provider value={field}>
            <div className={cx(styles.field, disabled && styles.disabled, focused && styles.focused, className)} data-testid={testId}>
                <CheckboxControl ref={ref} name={name} value={value} checked={checked} disabled={disabled} onChange={onChange} onFocus={onFocus} onBlur={onBlur} aria-describedby={count !== undefined ? `${id}-count` : undefined} {...rest} />
                <label htmlFor={id} className={styles.label}>
                    <CheckboxMark />
                    <CheckboxLabelText label={label} sublabel={sublabel} />
                    {count !== undefined ? <FieldCount>{count}</FieldCount> : null}
                </label>
            </div>
        </FieldContext.Provider>
    );
});

export const Radio = forwardRef(function Radio({ name, value, checked, label, onChange, className }, ref) {
    const id = useId();
    return (
        <div className={cx(styles.field, className)}>
            <input ref={ref} id={id} type="radio" className={styles.input} name={name} value={value} checked={checked} onChange={onChange} />
            <label htmlFor={id} className={styles.label}>
                <span className={cx(styles.box, styles.round)} aria-hidden="true" />
                <span className={styles.text}>{label}</span>
            </label>
        </div>
    );
});
