// The results page's GraphQL documents, as plain strings so that the build
// can parse them too. Fragments are named after the component that reads
// them.

export const TEXT = `
fragment LocalizedStringFields on LocalizedString { key text }
fragment LocalizedTextFields on LocalizedText { text tag { ...LocalizedStringFields } }
fragment IconFields on IconRef { name set size }
`;

export const LOCALIZED = `${TEXT}
fragment MoneyFields on MonetaryAmount { amount amountRounded currency formatted }
fragment LinkFields on LinkTarget { href target rel trackingId }
fragment ExperimentFields on ExperimentTracking { tag stage variant trackOn }
`;

export const PROPERTY_CARD = `
fragment PhotoFields on PhotoResource {
  id
  sizes { kind width height url }
  alt { ...LocalizedStringFields }
  dominantColor
}

fragment PropertyCardBasics on PropertyBasics {
  id
  name
  pageName
  isClosed
  accommodationType { id name { ...LocalizedTextFields } icon { ...IconFields } }
  starRating {
    value
    isEstimated
    symbol
    caption { ...LocalizedStringFields }
    a11yLabel { ...LocalizedStringFields }
    tocLink { ...LinkFields }
  }
  reviewSummary {
    score
    scoreFormatted
    word { ...LocalizedTextFields }
    count
    countText { ...LocalizedTextFields }
    secondary { key name { ...LocalizedStringFields } value formatted }
    showBadge
  }
  location {
    address
    postcode
    district { id name { ...LocalizedTextFields } score }
    coordinates { latitude longitude }
    distance { metres unit text { ...LocalizedTextFields } }
    transit { line station metres text { ...LocalizedTextFields } icon { ...IconFields } }
    showMapLink
  }
  photos {
    count
    main { ...PhotoFields }
    extra { ...PhotoFields }
  }
  chain { id name }
  flags { isNew isPreferred isPreferredPlus hasPhotos isSoldOut }
}

fragment UnitConfigurationFields on UnitConfiguration {
  id
  roomTypeId
  name { ...LocalizedTextFields }
  beds {
    count
    type { id name { ...LocalizedStringFields } icon { ...IconFields } }
    text { ...LocalizedStringFields }
  }
  size { value unit text { ...LocalizedStringFields } }
  occupancy { adults children text { ...LocalizedStringFields } }
  mealPlan { kind highlighted text { ...LocalizedTextFields } icon { ...IconFields } }
  cancellation { kind title { ...LocalizedTextFields } detail { ...LocalizedStringFields } }
  prepayment { kind title { ...LocalizedTextFields } detail { ...LocalizedStringFields } }
  scarcity { count urgency text { ...LocalizedTextFields } }
  price { ...MoneyFields }
}

fragment PriceDisplayFields on PriceDisplay {
  display { ...MoneyFields }
  strikethrough { ...MoneyFields }
  perNight { ...MoneyFields }
  nightsAndGuests { ...LocalizedTextFields }
  taxesLine { ...LocalizedTextFields }
  charges {
    included { label { ...LocalizedStringFields } amount { ...MoneyFields } }
    excluded { label { ...LocalizedStringFields } amount { ...MoneyFields } }
  }
  discounts {
    kind
    label { ...LocalizedTextFields }
    tooltip { ...LocalizedStringFields }
    style { variant emphasis }
  }
  a11yLabel { ...LocalizedStringFields }
}

fragment CardBadgeFields on CardBadge {
  __typename
  ... on DealBadge { id kind text { ...LocalizedTextFields } style { variant emphasis } tooltip { title { ...LocalizedTextFields } body { ...LocalizedTextFields } } }
  ... on QualityBadge { id kind text { ...LocalizedTextFields } icon { ...IconFields } tooltip { title { ...LocalizedTextFields } body { ...LocalizedTextFields } } }
  ... on SustainabilityBadge { id level text { ...LocalizedTextFields } icon { ...IconFields } tooltip { title { ...LocalizedTextFields } body { ...LocalizedTextFields } } }
  ... on ScarcityBadge { id count text { ...LocalizedTextFields } style { variant emphasis } }
}

fragment PropertyCardFields on PropertySearchCard {
  id
  position
  basics { ...PropertyCardBasics }
  priceDisplay { ...PriceDisplayFields }
  matchingUnits { ...UnitConfigurationFields }
  badges { ...CardBadgeFields }
  highlights { id text { ...LocalizedStringFields } icon { ...IconFields } }
  policies { freeCancellation noPrepayment payAtProperty texts { ...LocalizedStringFields } }
  recommendation { title { ...LocalizedTextFields } unitCount }
  memberDeal { eligible discountPercent text { ...LocalizedTextFields } }
  reviewSnippet { id author { name countryCode initial } text { ...LocalizedStringFields } language }
  wishlist { isSaved listId a11yLabel }
  links { details { ...LinkFields } availability { ...LinkFields } map { ...LinkFields } }
  tracking { ...ExperimentFields }
  a11y { label { ...LocalizedStringFields } priceSummary }
}
`;

export const FILTERS = `
fragment FilterOptionFields on FilterOption {
  urlId
  field
  value
  label { ...LocalizedTextFields }
  count { value formatted }
  a11yText
  trackingPayload
  selected
  disabled
  icon { ...IconFields }
  starCount
  tooltip { title { ...LocalizedTextFields } body { ...LocalizedTextFields } }
  tracking { ...ExperimentFields }
}

fragment FilterGroupFields on FilterGroup {
  field
  title { ...LocalizedTextFields }
  subtitle { ...LocalizedTextFields }
  position
  collapsedCount
  showAllLabel { ...LocalizedStringFields }
  control {
    __typename
    ... on CheckboxListControl { mode options { ...FilterOptionFields } }
    ... on RangeSliderControl {
      urlPrefix
      min
      max
      step
      selectedMin
      selectedMax
      currency
      minLabel { ...LocalizedStringFields }
      maxLabel { ...LocalizedStringFields }
      a11yLabel { ...LocalizedStringFields }
      histogram { from to count }
    }
    ... on StepperListControl {
      steppers { field urlPrefix label { ...LocalizedTextFields } min max value a11yLabel { ...LocalizedStringFields } }
    }
  }
  tracking { ...ExperimentFields }
  trackingPayload
}
`;

export const PROPERTY_SEARCH = `
query PropertySearch($input: SearchInput!) {
  accommodationSearch(input: $input) {
    searchId
    meta {
      title { ...LocalizedTextFields }
      totalCount
      totalCountText { ...LocalizedTextFields }
      destination { id type name country centre { latitude longitude } }
      breadcrumbs { label { ...LocalizedStringFields } link { ...LinkFields } }
      nights
      dates { checkin checkout }
    }
    appliedFilters { urlId label { ...LocalizedTextFields } }
    sorters {
      selected
      options { id label { ...LocalizedTextFields } a11yLabel { ...LocalizedStringFields } }
    }
    filters { ...FilterGroupFields }
    results { ...PropertyCardFields }
    pagination { page pageCount offset rowsPerPage pages { page offset label } }
    banners { id kind title { ...LocalizedTextFields } body { ...LocalizedTextFields } action { label { ...LocalizedStringFields } link { ...LinkFields } } image { url width height } position tracking { ...ExperimentFields } }
    tracking { ...ExperimentFields }
    mapPreview { image { url width height } label { ...LocalizedStringFields } centre { latitude longitude } }
    currency { code symbol name }
    seo { title robots canonical { ...LinkFields } }
    pageView { pageName searchType serverRequestId variant }
    messages { id kind text { ...LocalizedTextFields } }
    zeroResults { text { ...LocalizedTextFields } }
  }
}
${LOCALIZED}${PROPERTY_CARD}${FILTERS}`;

export const DESTINATION_AUTOCOMPLETE = `
query DestinationAutocomplete($input: AutocompleteInput!) {
  autocomplete(input: $input) {
    requestId
    results {
      id
      destType
      label { ...LocalizedTextFields }
      title
      subtitle
      icon { ...IconFields }
      highlights { start end }
      propertyCount
      destination { destId destType cityName countryName }
    }
  }
}
${TEXT}`;
